  // ---------- карточка тревоги и задание из двух инцидентов ----------
  function incOk(ans, id) {
    const I = INC[id];
    const c = ui.quizScore(I.c, ((ans.c || {})[id]) || []), f = ui.quizScore(I.f, ((ans.f || {})[id]) || []);
    const plasters = (((ans.f || {})[id]) || []).filter(i => I.f.options[i] && !I.f.options[i].ok).length;
    return { id, c, f, plasters, solved: c.ok && f.score >= 0.66, score: 0.5 * c.score + 0.5 * f.score };
  }
  function incCard(host, id, ctx) {
    const I = INC[id];
    const solved = ctx.readonly || (ctx.result && incOk(ctx.ans, id).solved);
    const card = TR.el(`<div class="card flat sdi-card ${solved ? 'solved' : ''}">
      <div class="sdi-h"><b>Тревога ${I.n} из 8 · ${esc(I.title)}</b><span class="chip ${solved ? 'ok' : 'bad'}">${esc(I.time)}</span></div>
      <div class="sdi-top"><div>${ui.say(I.who, esc(I.say))}</div>
        <div class="sdi-cnt ${solved ? 'ok' : 'live'}"><span class="k">${solved ? 'Остановлено' : 'Пострадавших клиентов'}</span><b class="tnum">${nf(I.cnt[0])}</b><small>${esc(I.cnt[2])}${solved ? '' : ' — пока причина не найдена и не вылечена'}</small></div></div>
      <div class="sdi-cap">Метрики на момент тревоги:</div>${metHTML(I.met)}
      <div class="sdi-cap">Что видно в логах — читайте внимательно:</div>
      <div style="min-width:0">${I.logs}</div>
      <div class="sdi-qc"></div><div class="sdi-qf"></div><div class="sdi-res"></div></div>`);
    host.appendChild(card);
    if (!solved) regCounter(TR.$('.sdi-cnt b', card), I.cnt[0], I.cnt[1]);
    ui.quiz(TR.$('.sdi-qc', card), Object.assign({}, I.c, { seed: 'sdi-c-' + id, value: ((ctx.ans.c || {})[id]) || [], readonly: ctx.readonly, reveal: ctx.result,
      onChange: v => { ctx.ans.c = Object.assign({}, ctx.ans.c, { [id]: v }); ctx.save(); if (!ctx.readonly) ctx.decide(`Инцидент «${I.title}»: причина`, plainT(I.c.options[v[0]] && I.c.options[v[0]].t) || '—'); } }));
    ui.quiz(TR.$('.sdi-qf', card), Object.assign({}, I.f, { q: I.f.q + ' <span class="small dim">Засчитывается лечение, пластырь снижает балл.</span>', seed: 'sdi-f-' + id, value: ((ctx.ans.f || {})[id]) || [], readonly: ctx.readonly, reveal: ctx.result,
      onChange: v => { ctx.ans.f = Object.assign({}, ctx.ans.f, { [id]: v }); ctx.save(); if (!ctx.readonly) ctx.decide(`Инцидент «${I.title}»: лечение`, v.map(i => plainT(I.f.options[i].t)).join('; ') || '—'); } }));
    if (ctx.result || ctx.readonly) TR.$('.sdi-res', card).innerHTML = ui.note('', 'Разбор', `<p>${esc(I.what)}</p><div class="sdi-post"><b>Строка постмортема:</b> ${esc(I.post)}</div>`);
  }
  function incTask(cfg) {
    const ids = cfg.ids;
    return {
      id: cfg.id, title: cfg.title, simple: cfg.simple, lead: cfg.lead,
      blank: () => Object.assign({ c: {}, f: {} }, cfg.justify ? { j: { text: '' } } : {}),
      reference: () => {
        const a = { c: {}, f: {} };
        ids.forEach(id => { const I = INC[id]; a.c[id] = [I.c.options.findIndex(o => o.ok)]; a.f[id] = I.f.options.map((o, i) => o.ok ? i : -1).filter(i => i >= 0); });
        if (cfg.justify) a.j = { text: plainT(cfg.justify.reference).replace(/\s+/g, ' ').trim(), self: cfg.justify.rubric.map(() => true) };
        return a;
      },
      render(el, ctx) {
        el.classList.add('sdi-root');
        ctx.ans.c = ctx.ans.c || {}; ctx.ans.f = ctx.ans.f || {};
        if (cfg.say) el.insertAdjacentHTML('beforeend', ui.say(cfg.say[0], cfg.say[1]));
        const box = mount(el, 'stack'); box.style.marginTop = '12px';
        ids.forEach(id => incCard(box, id, ctx));
        if (cfg.justify) {
          const j = mount(box, 'card flat');
          ui.justify(j, Object.assign({}, cfg.justify, { value: ctx.ans.j, readonly: ctx.readonly, onChange: v => { ctx.ans.j = v; ctx.save(); if (!ctx.readonly) ctx.decide('Постмортем', v.text || ''); } }));
        }
      },
      check(ans) {
        const per = ids.map(id => incOk(ans, id)), notes = [];
        per.forEach(p => {
          const I = INC[p.id], chosenC = ((ans.c || {})[p.id] || []).length, chosenF = ((ans.f || {})[p.id] || []).length;
          const good = ((ans.f || {})[p.id] || []).filter(i => I.f.options[i] && I.f.options[i].ok).length, all = I.f.options.filter(o => o.ok).length;
          notes.push({ ok: p.c.ok, html: `«${esc(I.title)}», причина: ${p.c.ok ? 'верно.' : chosenC ? 'не то. ' + I.hint : 'не выбрана.'}` });
          notes.push({ ok: p.f.score >= 0.66 ? (p.plasters ? 'warn' : true) : false, html: `«${esc(I.title)}», лечение: ${chosenF ? `настоящих мер ${good} из ${all}${p.plasters ? `, пластырей ${p.plasters} — они снимают симптом сегодня, но не мешают повторению` : ''}.` : 'ничего не выбрано.'}` });
        });
        let score = per.reduce((s, x) => s + x.score, 0) / per.length, ok = per.every(x => x.solved);
        if (cfg.justify) {
          const js = ui.justifyScore(ans.j), len = String((ans.j || {}).text || '').trim().length;
          notes.push({ ok: js >= 0.6, html: js ? `Постмортем: ${Math.round(js * 100)} %.` : len < cfg.justify.minLen ? `Напишите постмортем (от ${cfg.justify.minLen} символов) и сверьте с эталоном или с Верой.` : 'Сверьте постмортем с эталоном (кнопка под полем) или проверьте с Верой.' });
          score = score * 0.7 + js * 0.3; ok = ok && js >= 0.6;
        }
        return { ok, score: ok ? Math.max(score, 0.8) : Math.min(score, 0.79), summary: `Точность разбора: ${Math.round(score * 100)} %. Остановлено инцидентов: ${per.filter(x => x.solved).length} из ${per.length}.`, notes };
      },
      explain: cfg.explain,
      report: ans => per2report(ans, ids) + (cfg.justify ? `\n\nПостмортем:\n> ${String((ans.j || {}).text || '—').replace(/\n/g, '\n> ')}\nСамооценка: ${Math.round(ui.justifyScore(ans.j) * 100)} %.` : '')
    };
  }
  function per2report(ans, ids) {
    return ids.map(id => {
      const p = incOk(ans, id), I = INC[id], ci = ((ans.c || {})[id] || [])[0], fs = (ans.f || {})[id] || [];
      return `**${I.title}** — причина ${p.c.ok ? '✓' : '✗'}${I.c.options[ci] ? ` (${plainT(I.c.options[ci].t).slice(0, 90)}…)` : ''}; лечение ${Math.round(p.f.score * 100)} %, пластырей ${p.plasters}` + (fs.length ? '\n' + fs.map(i => `  - ${I.f.options[i].ok ? '✓' : '✗'} ${plainT(I.f.options[i].t)}`).join('\n') : '');
    }).join('\n');
  }

